def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    if n == 99:
        return 'D'

    my_ops, opp_ops = tuple(zip(*history))

    opp_c = opp_ops.count('C')
    opp_d = n - opp_c
    my_d = n - my_ops.count('C')
    my_last, opp_last = history[-1]

    opp_rate = (opp_c + 1.0) / (n + 2.0)

    # Learn whether the opponent punishes our defection in the next round.
    punish = 0
    forgive = 0
    for i in range(n - 1):
        if my_ops[i] == 'D':
            if opp_ops[i + 1] == 'D':
                punish += 1
            else:
                forgive += 1

    recent = opp_ops[-6:]
    recent_d = recent.count('D')

    # Against clearly uncooperative opponents, defect defensively.
    if opp_rate <= 0.30 or recent_d >= 4:
        return 'D'

    # If we have observed that our defections are not punished, exploit.
    if forgive > 0 and punish == 0 and opp_rate >= 0.55:
        return 'D'

    # If opponent just defected.
    if opp_last == 'D':
        # If we are in the middle of being punished for our own D, forgive once.
        if my_last == 'D':
            return 'C'
        if n >= 2 and my_ops[-2] == 'D':
            return 'C'
        # Otherwise retaliate against an unprovoked D.
        return 'D'

    # If we just defected and are not in confirmed exploit mode, step back.
    if my_last == 'D':
        return 'C'

    # One careful probe against opponents that have never defected.
    if opp_d == 0 and my_d == 0 and opp_rate >= 0.75 and n >= 17:
        return 'D'

    return 'C'
